#!/usr/bin/env bash
set -euo pipefail

task_script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
task_project_dir="$(cd -- "${task_script_dir}/.." && pwd)"
task_failures=0

require_pattern() {
  local task_file="$1"
  local task_pattern="$2"
  local task_description="$3"
  if rg -q -- "${task_pattern}" "${task_project_dir}/${task_file}"; then
    printf 'PASS  %s\n' "${task_description}"
  else
    printf 'FAIL  %s (%s)\n' "${task_description}" "${task_file}" >&2
    task_failures=$((task_failures + 1))
  fi
}

reject_pattern() {
  local task_file="$1"
  local task_pattern="$2"
  local task_description="$3"
  if rg -q -- "${task_pattern}" "${task_project_dir}/${task_file}"; then
    printf 'FAIL  %s (%s)\n' "${task_description}" "${task_file}" >&2
    task_failures=$((task_failures + 1))
  else
    printf 'PASS  %s\n' "${task_description}"
  fi
}

require_file() {
  local task_file="$1"
  local task_description="$2"
  if [[ -f "${task_project_dir}/${task_file}" ]]; then
    printf 'PASS  %s\n' "${task_description}"
  else
    printf 'FAIL  %s (%s)\n' "${task_description}" "${task_file}" >&2
    task_failures=$((task_failures + 1))
  fi
}

require_pattern_order() {
  local task_file="$1"
  local task_first_pattern="$2"
  local task_second_pattern="$3"
  local task_description="$4"
  local task_first_match
  local task_second_match
  local task_first_line
  local task_second_line

  task_first_match="$(rg -n -m 1 -- "${task_first_pattern}" \
    "${task_project_dir}/${task_file}" || true)"
  task_second_match="$(rg -n -m 1 -- "${task_second_pattern}" \
    "${task_project_dir}/${task_file}" || true)"
  task_first_line="${task_first_match%%:*}"
  task_second_line="${task_second_match%%:*}"
  if [[ "${task_first_line}" =~ ^[0-9]+$ && \
        "${task_second_line}" =~ ^[0-9]+$ ]] && \
      ((task_first_line < task_second_line)); then
    printf 'PASS  %s\n' "${task_description}"
  else
    printf 'FAIL  %s (%s)\n' "${task_description}" "${task_file}" >&2
    task_failures=$((task_failures + 1))
  fi
}

require_pattern_count() {
  local task_file="$1"
  local task_pattern="$2"
  local task_expected_count="$3"
  local task_description="$4"
  local task_actual_count

  task_actual_count="$(
    { rg -o -- "${task_pattern}" \
        "${task_project_dir}/${task_file}" 2>/dev/null || true; } |
      wc -l
  )"
  if [[ "${task_actual_count}" == "${task_expected_count}" ]]; then
    printf 'PASS  %s\n' "${task_description}"
  else
    printf 'FAIL  %s (%s: expected %s, got %s)\n' \
      "${task_description}" "${task_file}" "${task_expected_count}" \
      "${task_actual_count}" >&2
    task_failures=$((task_failures + 1))
  fi
}

reject_file() {
  local task_file="$1"
  local task_description="$2"
  if [[ -e "${task_project_dir}/${task_file}" ]]; then
    printf 'FAIL  %s (%s)\n' "${task_description}" "${task_file}" >&2
    task_failures=$((task_failures + 1))
  else
    printf 'PASS  %s\n' "${task_description}"
  fi
}

