task_throttle_header_fields=0
task_throttle_reject_checks=0
task_throttle_status_zeroes=0
task_throttle_unexpected=0
task_throttle_header_regex='^NonSecure/App/Inc/ecu_protocol[.]h:[0-9]+:[[:space:]]+int8_t[[:space:]]+throttle_percent;$'
task_throttle_reject_regex='^NonSecure/App/Src/ecu_protocol[.]c:[0-9]+:[[:space:]]+[(]control->throttle_percent[[:space:]]+!=[[:space:]]+0[)][[:space:]]+[|][|]$'
task_throttle_status_regex='^NonSecure/App/Src/ecu_protocol[.]c:[0-9]+:[[:space:]]+destination->throttle_percent[[:space:]]+=[[:space:]]+0;$'
mapfile -t task_throttle_matches < <(
  cd -- "${task_project_dir}"
  rg -n --no-heading -- 'throttle_percent' NonSecure/App || true
)
for task_throttle_match in "${task_throttle_matches[@]}"; do
  if [[ "${task_throttle_match}" =~ ${task_throttle_header_regex} ]]; then
    task_throttle_header_fields=$((task_throttle_header_fields + 1))
  elif [[ "${task_throttle_match}" =~ ${task_throttle_reject_regex} ]]; then
    task_throttle_reject_checks=$((task_throttle_reject_checks + 1))
  elif [[ "${task_throttle_match}" =~ ${task_throttle_status_regex} ]]; then
    task_throttle_status_zeroes=$((task_throttle_status_zeroes + 1))
  else
    task_throttle_unexpected=$((task_throttle_unexpected + 1))
  fi
done
if (( ${#task_throttle_matches[@]} == 4 &&
      task_throttle_header_fields == 2 &&
      task_throttle_reject_checks == 1 &&
      task_throttle_status_zeroes == 1 &&
      task_throttle_unexpected == 0 )); then
  printf 'PASS  Obsolete percentage control exists only in the frozen V1 reject/status-zero adapter\n'
else
  printf 'FAIL  Obsolete percentage control escaped the frozen V1 reject/status-zero adapter\n' >&2
  printf '       %s\n' "${task_throttle_matches[@]:-<no matches>}" >&2
  task_failures=$((task_failures + 1))
fi
