require_pattern Secure/App/Src/security_ota.c '^#define OTA_RECORD_SCHEMA_CURRENT[[:space:]]+2UL$' 'OTA replay journal uses the guarded schema-2 commit format'
require_pattern Secure/App/Src/security_ota.c 'record[.]commit_inverse = [(]uint32_t[)][(]~OTA_RECORD_COMMIT[)]' 'OTA journal final Flash word contains a non-sparse inverse guard'
require_pattern Secure/App/Src/security_ota.c 'record[.]generation_copy = record[.]generation' 'OTA journal atomically duplicates its generation in the commit word'
require_pattern Secure/App/Src/security_ota.c 'record[.]accepted_sequence_copy = record[.]accepted_sequence' 'OTA journal atomically duplicates its accepted sequence in the commit word'
require_pattern Secure/App/Src/security_ota.c 'HAL_ICACHE_Invalidate[(][)]' 'OTA invalidates cached Flash lines before write verification'
require_pattern Secure/App/Src/security_ota.c 'HAL_FLASH_Unlock_S[(][)]' 'Secure OTA storage uses the Secure-only Flash controller'
require_pattern Secure/App/Src/security_ota.c 'HAL_FLASH_Unlock_NS[(][)]' 'NonSecure image confirmation uses the NonSecure-only Flash controller'
reject_pattern Secure/App/Src/security_ota.c '^[[:space:]]*if .*HAL_FLASH_Unlock[(][)]' 'OTA code does not couple Secure and NonSecure Flash unlocks'
require_pattern Secure/App/Src/security_identity.c 'HAL_FLASH_Unlock_S[(][)]' 'Secure identity storage uses the Secure-only Flash controller'
require_pattern Secure/App/Src/security_identity.c 'HAL_ICACHE_Invalidate[(][)]' 'Secure identity records invalidate cached Flash lines before validation'
require_pattern Secure/App/Src/security_identity.c 'SECURITY_IDENTITY_ADDRESS_B, &record' 'Factory pairing persists and verifies the redundant B-sector record'
require_pattern Secure/App/Src/security_identity.c 'SecurityIdentity_RecordMatchesManifest[(]record_b, manifest[)]' 'Factory pairing finalizer verifies the committed B-sector identity'
require_pattern Secure/App/Src/valve_config_store.c 'HAL_FLASH_Unlock_S[(][)]' 'Secure valve calibration storage uses the Secure-only Flash controller'
require_pattern Secure/App/Src/valve_config_store.c 'HAL_ICACHE_Invalidate[(][)]' 'Valve calibration records invalidate cached Flash lines before validation'
reject_file Bootloader/OEMiROT/Src/boot_trace.c 'Temporary OEMiROT startup trace source is absent'
reject_file Secure/App/Src/security_boot_trace.c 'Temporary Secure startup trace source is absent'
reject_file NonSecure/App/Src/ecu_boot_trace.c 'Temporary NonSecure startup trace source is absent'
require_file tools/ecu_bench_test.py 'Guarded Ethernet actuator acceptance test is present'
require_pattern Secure/STM32H563xx_FLASH_s.ld 'ORIGIN = 0xc000000,    LENGTH = 1000K' 'Secure Flash excludes both valve parameter sectors and NSC'
require_pattern Secure/App/Linker/valve_config_flash_guard.ld '__data_source_end <= 0x0C0E0000' 'Additional linker guard protects all Secure persistent sectors after CubeMX regeneration'
require_pattern Secure/STM32H563xx_FLASH_s.ld 'ORIGIN = 0xc0fe000,    LENGTH = 8K' 'NSC linker region is the last Bank1 sector'
require_pattern NonSecure/STM32H563xx_FLASH_ns.ld 'ORIGIN = 0x8100000,    LENGTH = 1024K' 'NonSecure Flash linker region matches Bank2'

if ((task_failures != 0)); then
  printf '\nConfiguration audit failed: %d check(s).\n' "${task_failures}" >&2
  exit 1
fi

printf '\nConfiguration audit passed.\n'
